   !> SLIC (gaussian charges): combine and factor the operators for the solvent
   !>
   !> - Repeat with new solvent inputs as often as needed; the cavity operators are reused
   !> - Needs slic_assemble on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of slic
   !> @param[in] eps  relative permittivity of the solvent (inf for a conductor)
   !> @param[in] alpha  sLIC amplitude of the solvation-layer perturbation h
   !> @param[in] beta  sLIC steepness of h in the normal field (inverse field units)
   !> @param[in] gamma  sLIC offset of the transition of h
   !> @param[in] mu  sLIC shift of h
   !> @param[out] error  error handling; allocated on failure
   subroutine slic_medium(state, eps, alpha, beta, gamma, mu, error)
      !> State of slic
      type(slic_state), target, intent(inout) :: state
      !> Relative permittivity of the solvent (inf for a conductor)
      real(wp), intent(in) :: eps
      !> SLIC amplitude of the solvation-layer perturbation h
      real(wp), intent(in) :: alpha
      !> SLIC steepness of h in the normal field (inverse field units)
      real(wp), intent(in) :: beta
      !> SLIC offset of the transition of h
      real(wp), intent(in) :: gamma
      !> SLIC shift of h
      real(wp), intent(in) :: mu
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt
      integer :: stat
      real(wp) :: tmp1, tmp2

      if (state%matrix_free) then
         call slic_mf_medium(state, eps, alpha, beta, gamma, mu, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, "[slic_medium] call slic_assemble first")
         return
      end if
      state%s12 = 0.0_wp
      state%ready = 1
      ! Inputs that do not enter these outputs
      associate (unused1 => eps, unused2 => gamma)
      end associate

      state%beta = beta
      state%alpha = alpha
      state%mu = mu
      state%s8 = -gamma
      state%s9 = eps + 1.0_wp
      tmp1 = 1.0_wp/state%s9
      tmp2 = (-2.0_wp)*tmp1
      state%s10 = 1.0_wp + tmp2
      state%s11 = -state%s10
      state%s27 = state%beta**(2)

      state%ready = 2
   end subroutine slic_medium

   !> SLIC (gaussian charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs slic_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of slic
   !> @param[in] v  solute electrostatic potential at the surface points
   !> @param[in] vn  outward normal derivative of the solute potential at the surface points
   !> @param[out] energy  solvation energy
   !> @param[out] q  apparent surface charges
