      state%op1%a => state%a
      nl1%npt = npt
      nl1%solver => state%solver
      nl1%r => state%r
      nl1%a => state%a
      nl1%vn => vn
      nl1%alpha = state%alpha
      nl1%beta = state%beta
      nl1%mu = state%mu
      nl1%c1 => state%s7
      nl1%c2 = state%s8
      nl1%c3 = state%s10
      nl1%c4 = state%s11
