         call fatal_error(error, "[slic_mf_solve] v: wrong shape")
         return
      end if
      if (any(shape(vn) /= [npt])) then
         call fatal_error(error, "[slic_mf_solve] vn: wrong shape")
         return
      end if
      if (any(shape(q) /= [npt])) then
         call fatal_error(error, "[slic_mf_solve] q: wrong shape")
         return
      end if
      if (any(shape(grad_v) /= [npt])) then
         call fatal_error(error, "[slic_mf_solve] grad_v: wrong shape")
         return
      end if
      if (any(shape(grad_vn) /= [npt])) then
         call fatal_error(error, "[slic_mf_solve] grad_vn: wrong shape")
         return
      end if
      allocate (tmp1(npt), stat=stat)
      if (stat == 0) allocate (tmp2(npt), stat=stat)
      if (stat == 0) allocate (tmp6(npt), stat=stat)
      if (stat == 0) allocate (tmp137(npt), stat=stat)
      if (stat == 0) allocate (tmp138(npt), stat=stat)
      if (stat == 0) allocate (tmp159(npt), stat=stat)
      if (stat == 0) allocate (tmp171(npt), stat=stat)
      if (stat == 0) allocate (tmp172(npt), stat=stat)
      if (stat == 0) allocate (tmp173(npt), stat=stat)
      if (stat == 0) allocate (tmp175(npt), stat=stat)
      if (stat == 0) allocate (tmp186(npt), stat=stat)
      if (stat == 0) allocate (tmp187(npt), stat=stat)
      if (stat /= 0) then
         call fatal_error(error, "[slic_mf_solve] allocation failed")
         return
      end if
      state%ready = 2

      state%op2%npt = npt
      state%op2%npoint = npt
      state%op2%id = 2
      state%op2%points => state%r
      state%op2%r => state%r
      state%op2%n => state%n
      state%op2%k1 => state%k1
      state%op2%k2 => state%k2
      state%op2%xi => state%xi
      state%op2%a => state%a
      nl2%npt = npt
      nl2%solver => state%solver
      nl2%r => state%r
      nl2%n => state%n
      nl2%k1 => state%k1
      nl2%k2 => state%k2
      nl2%xi => state%xi
      nl2%a => state%a
      nl2%vn => vn
      nl2%alpha = state%alpha
      nl2%beta = state%beta
      nl2%mu = state%mu
      nl2%c1 = state%s8
      nl2%c2 = state%s10
      nl2%c3 = state%s11
      call nl2%solve(state%s12, error)
      if (allocated(error)) return
      state%s13 = state%a*state%s12
      do i = 1, npt
         tmp3 = state%k1(i) + state%k2(i)
         tmp4 = tmp3*state%xi(i)
         tmp5 = (-0.19947114020071635_wp)*tmp4
         tmp2(i) = tmp5
      end do
      tmp6 = tmp2*state%s13
      tmp1 = tmp6
      !$omp parallel &
      !$omp& private(i, j, tmp7) &
      !$omp& shared(npt, state, tmp1) &
      !$omp& default(private)
      allocate (tmp7(npt))
      block
         real(wp) :: tmp9, tmp10, tmp11, tmp12, tmp13, tmp14, tmp15, tmp16, tmp18, tmp19, tmp22, &
                     tmp26, tmp8

         !$omp do schedule(static)
         do j = 1, npt
