            tmp10 = state%xi(j)
            tmp11 = state%s1(j)
            tmp12 = state%s2(j)
            tmp13 = state%s3(j)
            tmp14 = state%s4(j)
            tmp15 = state%s5(j)
            tmp16 = state%s6(j)
            tmp18 = tmp10**(2)
            tmp19 = -tmp11
            tmp22 = -tmp12
            tmp26 = -tmp13
            tmp8 = 0.0_wp
            !$omp simd &
