            do i = 1, j - 1
               block
                  real(wp) :: tmp17, tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, &
                              tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, &
                              tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46

                  tmp20 = state%s1(i) + tmp19
                  tmp21 = tmp20**(2)
                  tmp23 = state%s2(i) + tmp22
                  tmp24 = tmp23**(2)
                  tmp25 = tmp21 + tmp24
                  tmp27 = state%s3(i) + tmp26
                  tmp28 = tmp27**(2)
                  tmp29 = tmp25 + tmp28
                  tmp30 = tmp18*tmp29
                  tmp31 = state%xi(i)**(2)
                  tmp32 = tmp30*tmp31
                  tmp33 = tmp31 + tmp18
                  tmp34 = (-81.0_wp)*tmp33
                  tmp35 = tmp32 + tmp34
                  tmp17 = 0.5_wp + sign(0.5_wp, tmp35)
                  tmp7(i) = tmp17
                  tmp36 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp35))
                  tmp37 = tmp29 + tmp36
                  tmp38 = 1.0_wp/sqrt(tmp37)
                  tmp39 = tmp38**(3)
                  tmp40 = state%s13(i)*tmp39
                  tmp41 = tmp14*tmp20
                  tmp42 = tmp23*tmp15
                  tmp43 = tmp41 + tmp42
                  tmp44 = tmp27*tmp16
                  tmp45 = tmp43 + tmp44
                  tmp46 = tmp40*tmp45
                  tmp8 = tmp8 + tmp46*tmp17
               end block
            end do
            !$omp simd &
            !$omp& reduction(+: tmp8)
            do i = j + 1, npt
               block
                  real(wp) :: tmp17, tmp20, tmp21, tmp23, tmp24, tmp25, tmp27, tmp28, tmp29, &
                              tmp30, tmp31, tmp32, tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, &
                              tmp39, tmp40, tmp41, tmp42, tmp43, tmp44, tmp45, tmp46

                  tmp20 = state%s1(i) + tmp19
                  tmp21 = tmp20**(2)
                  tmp23 = state%s2(i) + tmp22
                  tmp24 = tmp23**(2)
                  tmp25 = tmp21 + tmp24
                  tmp27 = state%s3(i) + tmp26
                  tmp28 = tmp27**(2)
                  tmp29 = tmp25 + tmp28
                  tmp30 = tmp18*tmp29
                  tmp31 = state%xi(i)**(2)
                  tmp32 = tmp30*tmp31
                  tmp33 = tmp31 + tmp18
                  tmp34 = (-81.0_wp)*tmp33
                  tmp35 = tmp32 + tmp34
                  tmp17 = 0.5_wp + sign(0.5_wp, tmp35)
                  tmp7(i) = tmp17
                  tmp36 = 1.0_wp + (0.0_wp - 1.0_wp)*(0.5_wp + sign(0.5_wp, tmp35))
                  tmp37 = tmp29 + tmp36
                  tmp38 = 1.0_wp/sqrt(tmp37)
                  tmp39 = tmp38**(3)
                  tmp40 = state%s13(i)*tmp39
                  tmp41 = tmp14*tmp20
                  tmp42 = tmp23*tmp15
                  tmp43 = tmp41 + tmp42
                  tmp44 = tmp27*tmp16
                  tmp45 = tmp43 + tmp44
                  tmp46 = tmp40*tmp45
                  tmp8 = tmp8 + tmp46*tmp17
