            end do
            do i = 1, npt
               if (i == j) cycle
               block
                  real(wp) :: tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, tmp55, &
                              tmp56, tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, &
                              tmp65, tmp66, tmp67, tmp68, tmp69, tmp70, tmp71, tmp72, tmp73, &
                              tmp74, tmp75, tmp76, tmp77, tmp78, tmp79, tmp80, tmp81, tmp82, &
                              tmp83, tmp84, tmp85, tmp86, tmp87, tmp88, tmp89, tmp90, tmp91, &
                              tmp92, tmp93, tmp94, tmp95, tmp96, tmp97, tmp98, tmp99, tmp100, &
                              tmp101, tmp102, tmp103, tmp104, tmp105, tmp106, tmp107, tmp108, &
                              tmp109, tmp110, tmp111, tmp112, tmp113, tmp114, tmp115, tmp116, &
                              tmp117, tmp118, tmp119, tmp120, tmp121, tmp122, tmp123, tmp124, &
                              tmp125, tmp126, tmp127, tmp128, tmp129, tmp130, tmp131, tmp132, &
                              tmp133, tmp134, tmp135, tmp136

                  if (tmp7(i) < 0.5_wp) then
                     tmp47 = state%xi(i)**(2)
                     tmp48 = tmp47 + tmp18
                     tmp49 = 0.25_wp*tmp48
                     tmp50 = state%s1(i) + tmp19
                     tmp51 = tmp50**(2)
                     tmp52 = state%s2(i) + tmp22
                     tmp53 = tmp52**(2)
                     tmp54 = tmp51 + tmp53
                     tmp55 = state%s3(i) + tmp26
                     tmp56 = tmp55**(2)
                     tmp57 = tmp54 + tmp56
                     tmp58 = tmp18*tmp57
                     tmp59 = tmp58*tmp47
                     tmp60 = -tmp59
                     tmp61 = tmp49 + tmp60
                     if (tmp61 >= 0.0_wp) then
                        tmp63 = tmp14*tmp50
                        tmp64 = tmp52*tmp15
                        tmp65 = tmp63 + tmp64
                        tmp66 = tmp55*tmp16
                        tmp67 = tmp65 + tmp66
                        tmp68 = 1.0_wp/sqrt(tmp48)
                        tmp69 = tmp68**(2)
                        tmp70 = tmp58*tmp69
                        tmp71 = tmp70*tmp47
                        tmp72 = 1.7449553823426687e-10_wp*tmp71
                        tmp73 = (-2.2614621755160987e-09_wp) + tmp72
                        tmp74 = tmp71*tmp73
                        tmp75 = 2.703922166377944e-08_wp + tmp74
                        tmp76 = tmp58*tmp75
                        tmp77 = tmp76*tmp69
                        tmp78 = tmp77*tmp47
                        tmp79 = (-2.961438563175843e-07_wp) + tmp78
                        tmp80 = tmp70*tmp79
                        tmp81 = tmp80*tmp47
                        tmp82 = 2.9458520444222863e-06_wp + tmp81
                        tmp83 = tmp18*tmp82
                        tmp84 = tmp83*tmp57
                        tmp85 = tmp84*tmp69
                        tmp86 = tmp85*tmp47
                        tmp87 = (-2.6339382985422794e-05_wp) + tmp86
                        tmp88 = tmp18*tmp87
                        tmp89 = tmp88*tmp57
                        tmp90 = tmp89*tmp69
                        tmp91 = tmp90*tmp47
                        tmp92 = 0.00020895910501768752_wp + tmp91
                        tmp93 = tmp58*tmp92
                        tmp94 = tmp93*tmp69
                        tmp95 = tmp94*tmp47
                        tmp96 = (-0.0014466399578147598_wp) + tmp95
                        tmp97 = tmp71*tmp96
                        tmp98 = 0.008548327023450852_wp + tmp97
                        tmp99 = tmp71*tmp98
                        tmp100 = (-0.0417918210035375_wp) + tmp99
                        tmp101 = tmp18*tmp100
                        tmp102 = tmp101*tmp57
                        tmp103 = tmp102*tmp69
                        tmp104 = tmp103*tmp47
                        tmp105 = 0.16119702387078752_wp + tmp104
                        tmp106 = tmp71*tmp105
                        tmp107 = (-0.45135166683820505_wp) + tmp106
                        tmp108 = tmp70*tmp107
                        tmp109 = tmp108*tmp47
                        tmp110 = 0.7522527780636751_wp + tmp109
                        tmp111 = tmp67*tmp110
                        tmp112 = tmp68*state%xi(i)
                        tmp113 = tmp112*tmp10
                        tmp114 = tmp113**(3)
                        tmp62 = tmp111*tmp114
