                        tmp115 = tmp14*tmp50
                        tmp116 = tmp52*tmp15
                        tmp117 = tmp115 + tmp116
                        tmp118 = tmp55*tmp16
                        tmp119 = tmp117 + tmp118
                        tmp120 = 1.0_wp/sqrt(tmp57)
                        tmp121 = tmp120**(3)
                        tmp122 = tmp119*tmp121
                        tmp123 = 1.0_wp/sqrt(tmp48)
                        tmp124 = tmp123*state%xi(i)
                        tmp125 = sqrt(tmp57)
                        tmp126 = tmp124*tmp125
                        tmp127 = tmp126*tmp10
                        tmp128 = erf(tmp127)
                        tmp129 = tmp127**(2)
                        tmp130 = -tmp129
                        tmp131 = exp(tmp130)
                        tmp132 = tmp126*tmp131
                        tmp133 = tmp132*tmp10
                        tmp134 = (-1.1283791670955126_wp)*tmp133
                        tmp135 = tmp128 + tmp134
                        tmp62 = tmp122*tmp135
                     end if
                     tmp136 = state%s13(i)*tmp62
                     tmp8 = tmp8 + tmp136
                  end if
               end block
            end do
            tmp1(j) = tmp1(j) + tmp8
         end do
         !$omp end do
      end block
      deallocate (tmp7)
      !$omp end parallel
      state%s14 = vn + tmp1
      tmp137 = 6.283185307179586_wp*state%s12
      tmp138 = state%s14 + tmp137
      state%s15 = -tmp138
      do i = 1, npt
         tmp139 = state%s15(i)*state%beta
         tmp140 = tmp139 + state%s8
         tmp141 = tanh(tmp140)
         tmp142 = tmp141**(2)
         tmp143 = -tmp142
         tmp144 = 1.0_wp + tmp143
         tmp145 = tmp144*state%s10
         tmp146 = tmp145*state%alpha
         tmp147 = tmp146*state%beta
         tmp148 = tmp147*state%s12(i)
         tmp149 = (-12.566370614359172_wp)*tmp148
         state%s16(i) = tmp149
      end do
      state%op2%c1 => state%s16
      do i = 1, npt
         tmp150 = state%s15(i)*state%beta
         tmp151 = tmp150 + state%s8
         tmp152 = tanh(tmp151)
         tmp153 = state%alpha*tmp152
         tmp154 = tmp153 + state%mu
         tmp155 = state%s10*tmp154
         tmp156 = (-2.0_wp)*tmp155
         tmp157 = 1.0_wp + tmp156
         tmp158 = 6.283185307179586_wp*tmp157
         state%s17(i) = tmp158
      end do
      state%op2%c2 => state%s17
      state%op2%c3 = state%s11
